import time
import logging
from taf.internal.managedobject import ManagedObject
from taf.internal.managed.ssh.managed_ssh_connection import ManagedSshConnection
from taf.hw.vertex.exception import UnexpectedType


class SshConnection(ManagedObject):
    _VERTEX_COMMAND_PROMPT = r'Vertex>'
    _VERTEX_HOSTNAME = r'Spirent-Vertex'
    _BYTE_SIZE_PRE_RECV = 65535
    _WAITTING_INTERVAL_PRE_RECV = 0.1

    def __init__(self, host, port, proxy, proxy_username, proxy_password, **kwargs):
        super(SshConnection, self).__init__()
        self._ssh_connection = ManagedSshConnection(proxy, proxy_username, proxy_password)
        self.add_prerequisite(self._ssh_connection)
        self._vertex_channel = None
        self._socket = (host, port)
        self._timeout = int(kwargs.get('timeout', 2))

    def _setup(self):
        self.connect()

    def _teardown(self):
        self.disconnect()

    def connect(self):
        self._ssh_connection.setup()
        self._vertex_channel = self._ssh_connection.ssh_connection.invoke_direct_tcpip(destination_address=self._socket)
        self._read_until_end(self._vertex_channel, self._timeout)

    def execute_command(self, command):
        self._vertex_channel.send(self._convert_command_to_byte(command))
        return self._read_until_end(self._vertex_channel, self._timeout)

    def disconnect(self):
        self._ssh_connection.teardown()

    def check_if_vertex_host(self):
        return self._VERTEX_HOSTNAME in self._ssh_connection.ssh_connection.execute("echo $HOSTNAME")

    def create_dir(self, dir_path):
        self._ssh_connection.ssh_connection.execute("mkdir {}".format(dir_path))

    def remove_file(self, file_path):
        self._ssh_connection.ssh_connection.execute("rm -f {}".format(file_path))

    def upload_file(self, local_path, remote_path):
        fp = self._ssh_connection.ssh_connection.files
        log_msg = "Uploading file(s) to {}:\n"
        log_msg += "Remote path: {}"
        log_msg = log_msg.format(self._ssh_connection.ssh_connection, remote_path)
        logging.info(log_msg)

        logging.info("Uploading file: {}".format(local_path))
        fp.put(local_path, remote_path)
        return remote_path

    def _read_until_end(self, channel, timeout):
        output = r''
        start_time = time.time()
        while (time.time() - float(start_time)) < timeout:
            if self._check_prompt(output):
                break
            if channel.recv_ready():
                output += channel.recv(self._BYTE_SIZE_PRE_RECV).decode('unicode-escape')
            time.sleep(self._WAITTING_INTERVAL_PRE_RECV)
        return output.strip(self._VERTEX_COMMAND_PROMPT).strip()

    def _check_prompt(self, output):
        return self._VERTEX_COMMAND_PROMPT in output

    @staticmethod
    def _convert_command_to_byte(command):
        if isinstance(command, str):
            command = command + '\r\n'
            return command.encode('utf-8')
        elif isinstance(command, bytes):
            return command
        else:
            raise UnexpectedType("{} should not be {} type".format(command, type(command)))
